const WebSocket = require('ws');
const ws = new WebSocket('ws://127.0.0.1:18881/ws/echo');
ws.on('open', () => { console.log('OPEN'); ws.send('ping'); });
ws.on('message', (data) => { console.log('MSG:', data.toString()); ws.close(); });
ws.on('error', (e) => console.log('ERR', e.message));
ws.on('close', () => console.log('CLOSED'));
setTimeout(()=>process.exit(0), 5000);
